def solve(inputs: dict) -> float:
    terms = inputs['cf_terms']

    # Initialize: p_{-1} = 1, p_0 = a_0
    p_prev2 = 1  # p_{-1}
    p_prev1 = terms[0]  # p_0

    # Apply recurrence: p_n = a_n * p_{n-1} + p_{n-2}
    for i in range(1, len(terms)):
        a = terms[i]
        p_curr = a * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_curr

    return float(p_prev1)

